<div data-version="<%= @version %>" data-phase="<%= @game.phase %>">
  <% if @game.waiting? %>
    <% url = play_url(@game.code) %>
    <div class="lobby">
      <div>
        <div class="screen__kicker">Join the game</div>
        <h1 class="lobby__title"><%= @game.title %></h1>
        <p class="lobby__join">Scan the code or open</p>
        <div class="lobby__url"><%= url %></div>
        <span class="counter-pill" data-counter><%= @counter %></span>
        <% if @game.question_count.zero? %><p>No active questions. Starting will end this game.</p><% end %>
      </div>
      <div class="qr" role="img" aria-label="QR code for the join link"><%= join_qr(url) %></div>
    </div>
  <% elsif @game.ended? %>
    <p class="screen__kicker"><%= @game.title %></p>
    <h1 class="lobby__title">The quiz is over</h1>
  <% else %>
    <div class="stage-question__num">Question <%= @game.number %> of <%= @game.question_count %></div>
    <h1 class="stage-question__body"><%= @question.body %></h1>
    <ol class="stage-options <%= 'stage-options--results' if @game.closed? %>">
      <% @question.options.each_with_index do |option, i| %>
        <% correct = @game.closed? && option['correct'] %>
        <li class="stage-option <%= 'is-correct' if correct %>">
          <span class="stage-option__letter" aria-hidden="true"><%= option_letter(i) %></span>
          <span class="stage-option__title"><%= option['text'] %></span>
          <% if correct %><span class="stage-option__mark">Correct</span><% end %>
          <% if @game.closed? %><span class="stage-option__count"><%= @counts.fetch(i, 0) %></span><% end %>
        </li>
      <% end %>
    </ol>
  <% end %>
  <footer class="screen-controls">
    <div class="screen-controls__info">
      <%= link_to "Back to quiz", moderate_quiz_path(@game.quiz_id) %>
      <% if @game.open? %><span class="answers-counter" data-counter><%= @counter %></span><% end %>
    </div>
    <% unless @game.ended? %>
      <% command, label = game_control(@game) %>
      <%= button_to label, moderate_game_path(@game), method: :patch, params: { command: command, number: @game.number }, class: "btn btn--pink btn--lg" %>
    <% end %>
  </footer>
</div>
