module GamesHelper
  def game_control(game)
    if game.waiting?
      %w[start Start]
    elsif game.open?
      %w[finish Finish]
    elsif game.number == game.question_count
      ["end", "End quiz"]
    else
      %w[next Next]
    end
  end

  def join_qr(url)
    # Only library-generated shapes are inserted. The payload is encoded into
    # the modules; the URL itself is never interpolated into the SVG markup.
    RQRCode::QRCode.new(url, level: :m).as_svg(module_size: 1, offset: 4, use_path: true,
      fill: "fff", viewbox: true).sub(/\A<\?xml[^>]*>/, "").html_safe
  end
end
