// change; a check-in repairs missed notifications AND renews this tab's lease.
// Only the moderator needs a fast counter poll, independent of audience size.
function followGame(root) {
  const stage = root.querySelector('[data-stage]');
  const errorBox = root.querySelector('[data-error]');
  const phone = !!root.dataset.code;
  const tab = Array.from(crypto.getRandomValues(new Uint8Array(16)), n => n.toString(16).padStart(2, '0')).join('');
  const csrf = document.querySelector('meta[name="csrf-token"]')?.content;
  const headers = { 'X-Requested-With': 'XMLHttpRequest' };
  if (csrf) headers['X-CSRF-Token'] = csrf;
  let timer, consumer, connected = false, paused = false, busy = false, dirty = false, failures = 0;
  const writes = [];
  const ended = () => stage.firstElementChild.dataset.phase === 'ended';

  function notice(message) {
    errorBox.textContent = message;
    errorBox.hidden = !message;
  }

  function request(url, body) {
    // A moderator might have opened a Basic-auth URL with userinfo. Keep the
    // established same-origin credentials, not the user/password in the URL.
    const target = new URL(url, location.origin);
    target.username = target.password = '';
    return fetch(target, { method: body ? 'POST' : 'GET', body, headers, cache: 'no-store', signal: AbortSignal.timeout(10000) });
  }

  async function sync() {
    const params = new URLSearchParams({ version: stage.firstElementChild.dataset.version });
    if (phone) params.set('tab', tab);
    const url = root.dataset.sync;
    const response = await (phone ? request(url, params) : request(`${url}?${params}`));
    if (!response.ok) throw new Error('Sync failed');
    await apply(response);
  }

  async function apply(response) {
    if (failures) notice('');
    failures = 0;
    if (response.status === 204) return;
    const update = await response.json();
    if (update.html) {
      stage.innerHTML = update.html;
      notice('');
    } else if (update.counter) {
      const counter = stage.querySelector('[data-counter]');
      if (counter && counter.textContent !== update.counter) counter.textContent = update.counter;
    }
  }

  // Serialize clicks and refreshes. A slow response must not rewind the UI,
  // reorder a player's taps, or write an old choice onto a new question.
  async function drain() {
    if (busy || paused || ended()) return;
    busy = true;
    clearTimeout(timer);
    try {
      while (!paused && !ended() && (dirty || writes.length)) {
        if (writes.length) {
          const { url, body } = writes.shift();
          body.set('version', stage.firstElementChild.dataset.version);
          const response = await request(url, body);
          if (response.status === 422) notice((await response.json()).error);
          else if (!response.ok) throw new Error('Save failed');
          else await apply(response);
        } else {
          dirty = false;
          await sync();
        }
      }
    } catch {
      // Never replay an uncertain write automatically after reconnecting.
      writes.length = 0;
      failures++;
      notice('Connection interrupted. Reconnecting… Check your selection and retry if needed.');
    } finally {
      busy = false;
      if (ended()) consumer?.disconnect();
      if (!paused && !ended()) {
        const interval = failures ? Math.min(12000, 800 * 2 ** failures) : phone ? (connected ? 15000 : 1200) : 800;
        timer = setTimeout(refresh, interval * (1 + Math.random() * 0.2));
      }
    }
  }

  function refresh() { dirty = true; drain(); }

  root.addEventListener('submit', event => {
    event.preventDefault();
    notice('');
    const form = event.target;
    const body = new URLSearchParams(new FormData(form, event.submitter));
    if (phone) body.set('tab', tab);
    writes.push({ url: form.action, body });
    drain();
  });

  if (phone && !ended() && window.ActionCable && window.WebSocket) {
    consumer = ActionCable.createConsumer('/cable');
    consumer.subscriptions.create({ channel: 'GameChannel', code: root.dataset.code, tab }, {
      connected() { connected = true; refresh(); },
      disconnected() { connected = false; refresh(); },
      received() { refresh(); }
    });
  }
  addEventListener('pagehide', () => {
    paused = true;
    clearTimeout(timer);
    consumer?.disconnect();
    if (phone && !ended() && stage.firstElementChild.dataset.version !== 'join') {
      const params = new URLSearchParams({ tab });
      if (csrf) params.set('authenticity_token', csrf);
